cd /root/schema_semantic_constrained_ie && source /root/miniconda3/etc/profile.d/conda.sh && conda activate base && python3 -c "
import json
from collections import defaultdict

samples = []
with open('outputs/phase2_scierc_full_s2.jsonl') as f:
    for line in f:
        if line.strip():
            samples.append(json.loads(line))

vc_violations = set()
total_vc = 0
for s in samples:
    parsed = s.get('parsed_output', {})
    entities = parsed.get('entities', [])
    relations = parsed.get('relations', [])
    mention_types = {}
    for ent in entities:
        k = ent.get('text','').lower().strip()
        mention_types.setdefault(k, set()).add(ent.get('type',''))
    for rel in relations:
        hk = rel.get('head','').lower().strip()
        tk = rel.get('tail','').lower().strip()
        ht = rel.get('head_type','')
        tt = rel.get('tail_type','')
        if ht: mention_types.setdefault(hk, set()).add(ht)
        if tt: mention_types.setdefault(tk, set()).add(tt)
    for m, types in mention_types.items():
        if len(types) > 1:
            total_vc += 1
            vc_violations.add((s['doc_id'], m))

evr_violations = set()
evr_count = 0
for s in samples:
    parsed = s.get('parsed_output', {})
    entities = parsed.get('entities', [])
    relations = parsed.get('relations', [])
    etype_map = {}
    for ent in entities:
        etype_map[ent['text']] = ent['type']
    for rel in relations:
        for span_key, type_key in [('head','head_type'),('tail','tail_type')]:
            span = rel[span_key]
            rtype = rel[type_key]
            if span in etype_map and etype_map[span] != rtype:
                evr_count += 1
                evr_violations.add((s['doc_id'], span))

wr_violations = set()
for s in samples:
    relations = s.get('parsed_output', {}).get('relations', [])
    entity_role_types = defaultdict(set)
    for rel in relations:
        entity_role_types[(rel['head'], 'head')].add(rel['head_type'])
        entity_role_types[(rel['tail'], 'tail')].add(rel['tail_type'])
    for (ent, role), types in entity_role_types.items():
        if len(types) > 1:
            wr_violations.add((s['doc_id'], ent, role))

wr_mentions = set((d, e) for d, e, r in wr_violations)
evr_lower = set((d, e.lower().strip()) for d, e in evr_violations)
wr_lower = set((d, e.lower().strip()) for d, e, r in wr_violations)
union = evr_lower | wr_lower

print(f'violation_checker CF count: {total_vc}')
print(f'EVR slot-level: {evr_count}, unique (doc,span): {len(evr_violations)}, lowered: {len(evr_lower)}')
print(f'WR: {len(wr_violations)}, unique (doc,mention): {len(wr_mentions)}, lowered: {len(wr_lower)}')
print(f'union: {len(union)}, vc: {len(vc_violations)}')
print(f'vc - union: {len(vc_violations - union)}')
print(f'union - vc: {len(union - vc_violations)}')
for item in sorted(vc_violations - union)[:5]:
    print(f'  vc only: {item}')
for item in sorted(union - vc_violations)[:5]:
    print(f'  union only: {item}')
print(f'WR ∩ EVR: {len(wr_lower & evr_lower)}')
print(f'WR - EVR: {len(wr_lower - evr_lower)}')
"

